    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product((False, True), repeat=m):
        # bits[v-1] is the value of variable v
        def lit_value(lit):
            val = bits[abs(lit) - 1]
            return val if lit > 0 else not val

        if all(any(lit_value(l) for l in clause) for clause in clauses):
            return True
    return False


def solve_nae_three_sat(instance: dict) -> bool:
    """Yes iff some assignment makes every clause not all-equal."""
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product((False, True), repeat=m):
        def lit_value(lit):
            val = bits[abs(lit) - 1]
            return val if lit > 0 else not val

        ok = True
        for clause in clauses:
            vals = [lit_value(l) for l in clause]
            if all(vals) or not any(vals):
                ok = False
                break
        if ok:
            return True
    return False


# ----------------------------------------------------------------------
# Instance generators (small, valid source instances).


def random_source_instance(rng: random.Random, max_vars: int = 5, max_clauses: int = 4):
    m = rng.randint(0, max_vars)
    n_clauses = rng.randint(0, max_clauses)
    clauses = []
    if m >= 3:
        for _ in range(n_clauses):
            vs = rng.sample(range(1, m + 1), 3)
            clause = [v if rng.random() < 0.5 else -v for v in vs]
            clauses.append(clause)
    else:
        n_clauses = 0
    return {"num_vars": m, "clauses": clauses}


def all_small_source_instances():
    """Exhaustively enumerate a family of small valid source instances."""
    for m in range(0, 5):
        if m < 3:
            yield {"num_vars": m, "clauses": []}
            continue
        # all clauses over variables 1..m (unordered triples, all sign patterns)
        all_clauses = []
        for triple in itertools.combinations(range(1, m + 1), 3):
            for signs in itertools.product((1, -1), repeat=3):
                all_clauses.append([s * v for s, v in zip(signs, triple)])
